{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Eluxadoline, the closest analogue sharing an aryl carboxylic acid, multiple amide/urea-like linkages, and methoxy-substituted aromatics, has an absolute oral bioavailability of only 1.02% in humans due to poor GI permeability, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Terameprocol, which contains dimethoxyphenyl motifs similar to the query's dimethoxybenzyl group, has an absolute oral bioavailability of approximately 2% in patients, supporting a low oral bioavailability prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Almorexant, a large amide-containing molecule with dimethoxyphenyl substitution, has an absolute oral bioavailability of 11.2% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Revefenacin, a polar amide/carbamate-containing drug with very low oral absorption, has an absolute oral bioavailability of <3%, supporting low F for a highly polar amide/urea-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Moexipril, which shares a carboxylic acid and dimethoxyaryl motif, has an oral bioavailability of 22% in humans, slightly above the threshold; however, it is an ester prodrug and less transferable to the non-ester query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, polar molecule containing a free carboxylic acid, multiple amide linkages, and a urea, with no basic center to offset the acid. The closest and most transferable experimental analogues (eluxadoline, terameprocol, almorexant, revefenacin) all show low oral bioavailability below 20%, while the high-F analogues are less similar or are ester prodrugs/basic amines. Therefore, low oral bioavailability at the F >= 20% threshold is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All evidence comes from analogues with modest Morgan similarity scores (~0.24-0.28).",
    "No query-specific permeability, solubility, or first-pass metabolism data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

